/**
 * Cuts Bootstrap Icons down to the icons the code uses. Run `npm run icon-subset` after adding or removing an
 * icon; the generated files are committed (like `npm run icons`), and tests/lint/icon-subset.test.ts fails when
 * the code uses an icon the subset lacks.
 *
 * Writes:
 * - src/styles/_icons.scss: the @font-face, the base `.bi` rules and one `.bi-<name>::before` rule per icon,
 *   with the code points of the full font (so the full stylesheet's names keep working);
 * - src/styles/fonts/bootstrap-icons-subset.woff2: the font with only those glyphs.
 *
 * Subsetting needs Python's fontTools and brotli (`pip install fonttools brotli`); nothing else in the project
 * does, which is why the outputs are committed. Set PYTHON to pick the interpreter.
 */
import { spawnSync } from 'node:child_process';
import { mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { format, resolveConfig } from 'prettier';
import { iconCodepoints, usedIcons } from '../vite-plugins/icon-usage.ts';

const root = join(import.meta.dirname, '..');
const styles = join(root, 'src', 'styles');
const fontOut = join(styles, 'fonts', 'bootstrap-icons-subset.woff2');
const fontIn = join(
  root,
  'node_modules',
  'bootstrap-icons',
  'font',
  'fonts',
  'bootstrap-icons.woff2',
);
const version = JSON.parse(
  readFileSync(join(root, 'node_modules', 'bootstrap-icons', 'package.json'), 'utf8'),
).version;

const known = iconCodepoints(root);
const names = usedIcons(root, known);
const hex = (name) => known.get(name).toString(16);

mkdirSync(join(styles, 'fonts'), { recursive: true });
const unicodes = names.map((name) => `U+${hex(name).toUpperCase()}`).join(',');
const python = process.env.PYTHON ?? 'python';
const result = spawnSync(
  python,
  [
    '-m',
    'fontTools.subset',
    fontIn,
    `--unicodes=${unicodes}`,
    '--flavor=woff2',
    `--output-file=${fontOut}`,
    // An icon font has no text to shape and nothing to hint at these sizes.
    '--layout-features=',
    '--no-hinting',
    '--desubroutinize',
    '--name-IDs=',
    '--no-notdef-outline',
  ],
  { encoding: 'utf8' },
);
if (result.error || result.status !== 0) {
  console.error(result.stderr || String(result.error));
  console.error('Subsetting needs Python with fontTools and brotli: pip install fonttools brotli');
  process.exit(1);
}

const rules = names.map((name) => `.bi-${name}::before { content: "\\${hex(name)}"; }`).join('\n');
const scssPath = join(styles, '_icons.scss');
const scss = `// GENERATED by scripts/generate-icon-subset.mjs (npm run icon-subset): do not edit.
// Bootstrap Icons ${version} cut down to the ${names.length} icons the code uses, with the full font's
// code points. The font is self-hosted and preloaded by vite-plugins/html-head.ts. font-display stays block:
// an icon has no fallback text, so a late font should leave a gap, not show another font's box.

@font-face {
  font-display: block;
  font-family: 'bootstrap-icons';
  src: url('fonts/bootstrap-icons-subset.woff2') format('woff2');
}

.bi::before,
[class^='bi-']::before,
[class*=' bi-']::before {
  display: inline-block;
  font-family: 'bootstrap-icons' !important;
  font-style: normal;
  font-weight: normal !important;
  font-variant: normal;
  text-transform: none;
  line-height: 1;
  vertical-align: -0.125em;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

${rules}
`;
// Written the way Prettier would, so `npm run lint` accepts the committed file.
writeFileSync(
  scssPath,
  await format(scss, { ...(await resolveConfig(scssPath)), filepath: scssPath }),
);
console.log(
  `${names.length} icons, font ${statSync(fontOut).size} bytes (full font: ${statSync(fontIn).size}).`,
);
